//! Worldgen P28 semantic-parity contract for cross-language and cross-site artifacts.
use bioprism_foundation::{PRECLINICAL_BOUNDARY,RESEARCH_CONTRACT_SCHEMA_VERSION};use bioprism_ids::ContentHash;use serde::{Deserialize,Serialize};use serde_json::json;use std::collections::BTreeSet;use thiserror::Error;
pub const FEATURE_ID:&str="AFA-worldgen-P28-F01";pub const CONTRACT_VERSION:&str="worldgen-local-semantic-parity/1.0";pub const CONTENT_TYPE:&str="application/vnd.aurora.worldgen.semantic-parity-receipt-1+json";
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct ParityArtifact4{pub artifact_id:String,pub language:String,pub semantic_profile:String,pub canonical_digest:ContentHash,pub schema_digest:ContentHash,pub provenance_digest:ContentHash,pub replay_identity:ContentHash,pub field_order:Vec<String>,pub local:bool,pub aggregate_only:bool,pub evidence_state:String,pub negative_result:bool}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct SemanticParityRequest4{pub request_id:String,pub scope:String,pub artifacts:Vec<ParityArtifact4>,pub required_language_order:Vec<String>,pub required_field_order:Vec<String>,pub policy_allowed:bool,pub protected_closure:bool,pub signed_approval:bool,pub network_available:bool,pub raw_data_local:bool,pub aggregate_only:bool,pub replay_identity:ContentHash,pub adversarial_events:Vec<String>,pub boundary:String}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct SemanticParityArtifact4{pub artifact_id:String,pub content_type:String,pub content_hash:ContentHash,pub semantic_loss:Vec<String>,pub provenance_digests:Vec<ContentHash>,pub boundary:String}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct SemanticParityCard7{pub schema_version:String,pub contract_version:String,pub feature_id:String,pub mode:String,pub scale:String,pub request_id:String,pub disposition:String,pub language_order:Vec<String>,pub artifact_order:Vec<String>,pub matched_order:Vec<String>,pub mismatched_order:Vec<String>,pub omitted_order:Vec<String>,pub unknown_order:Vec<String>,pub negative_evidence_order:Vec<String>,pub field_order:Vec<String>,pub semantic_loss_order:Vec<String>,pub replay_identity:ContentHash,pub parity_digest:ContentHash,pub artifact:SemanticParityArtifact4,pub effect_receipts:Vec<String>,pub raw_data_local:bool,pub aggregate_only:bool,pub boundary:String}
#[derive(Debug,Error,Clone,PartialEq,Eq)]pub enum SemanticParityError{#[error("invalid semantic-parity request: {0}")]Invalid(String),#[error("semantic-parity card failed validation: {0}")]Output(String)}
fn ord(v:&[String])->bool{v.windows(2).all(|p|p[0]<p[1])}fn dig(v:&ContentHash)->bool{v.as_str().len()==64&&v.as_str().bytes().all(|b|b.is_ascii_hexdigit())}fn ne(v:&str)->bool{!v.trim().is_empty()}
pub fn manifest(id:&str,version:&str,scale:&str,mode:&str)->serde_json::Value{json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"capability_id":id,"version":version,"owner_crate":"worldgen","consumers":["parity steward","SDK maintainer","federation operator","release auditor"],"behavior":format!("compare semantic artifacts with explicit mismatch and loss evidence at {scale} ({mode})"),"value":"prevents cross-language or cross-site drift from being mistaken for reproducible research state","input_schema":"SemanticParityRequest4@1","output_schema":"SemanticParityCard7@1","effects":["emit:parity-card","block:unsafe-release"],"permissions":["read:local-artifact-summaries"],"determinism":"byte_stable","autonomy_tier":"A1","boundary":PRECLINICAL_BOUNDARY})}
impl SemanticParityCard7{pub fn validate(&self)->Result<(),SemanticParityError>{if self.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||!ne(&self.contract_version)||!ne(&self.feature_id)||!ne(&self.mode)||!ne(&self.scale)||!ne(&self.request_id)||self.boundary!=PRECLINICAL_BOUNDARY||!self.raw_data_local||!self.aggregate_only||self.artifact_order.is_empty()||!ord(&self.language_order)||!ord(&self.artifact_order)||!ord(&self.matched_order)||!ord(&self.mismatched_order)||!ord(&self.omitted_order)||!ord(&self.unknown_order)||!ord(&self.negative_evidence_order)||!ord(&self.field_order)||!ord(&self.semantic_loss_order)||!dig(&self.replay_identity)||!dig(&self.parity_digest)||self.artifact.content_type!=CONTENT_TYPE||self.artifact.content_hash!=self.parity_digest||self.artifact.boundary!=PRECLINICAL_BOUNDARY{return Err(SemanticParityError::Output("parity identity, ordering, locality, digest, or artifact is invalid".into()))}let ids=BTreeSet::from_iter(self.artifact_order.iter().cloned());let parts=self.matched_order.iter().chain(&self.mismatched_order).chain(&self.omitted_order).chain(&self.unknown_order).cloned().collect::<Vec<_>>();if ids.len()!=self.artifact_order.len()||parts.len()!=ids.len()||BTreeSet::from_iter(parts)!=ids{return Err(SemanticParityError::Output("parity states do not partition".into()))}Ok(())}}
pub fn compare(request:&SemanticParityRequest4,id:&str,version:&str,scale:&str,mode:&str)->Result<SemanticParityCard7,SemanticParityError>{if !ne(&request.request_id)||!ne(&request.scope)||request.artifacts.is_empty()||request.required_language_order.is_empty()||request.required_field_order.is_empty()||!dig(&request.replay_identity)||request.boundary!=PRECLINICAL_BOUNDARY||!request.raw_data_local||!request.aggregate_only||!ord(&request.required_language_order)||!ord(&request.required_field_order)||!ord(&request.adversarial_events){return Err(SemanticParityError::Invalid("parity identity, required languages/fields, digest, ordering, locality, or boundary is invalid".into()))}let mut rows=request.artifacts.clone();rows.sort_by(|a,b|a.artifact_id.cmp(&b.artifact_id));let mut seen=BTreeSet::new();let mut artifacts=Vec::new();let mut languages=BTreeSet::new();let mut fields=BTreeSet::new();let mut matched=BTreeSet::new();let mut mismatched=BTreeSet::new();let mut omitted=BTreeSet::new();let mut unknown=BTreeSet::new();let mut negative=BTreeSet::new();let mut loss=BTreeSet::new();let mut provenance=BTreeSet::new();let baseline=rows.first().map(|a|a.canonical_digest.clone());for a in &rows{if !seen.insert(a.artifact_id.clone())||!ne(&a.artifact_id)||!ne(&a.language)||!ne(&a.semantic_profile)||!dig(&a.canonical_digest)||!dig(&a.schema_digest)||!dig(&a.provenance_digest)||!dig(&a.replay_identity)||!ord(&a.field_order)||!a.local||!a.aggregate_only{return Err(SemanticParityError::Invalid("artifact identity, ordering, digest, or locality is invalid".into()))}artifacts.push(a.artifact_id.clone());languages.insert(a.language.clone());fields.extend(a.field_order.iter().cloned());provenance.insert(a.provenance_digest.clone());if a.negative_result{negative.insert(format!("{}:negative-result",a.artifact_id));}if a.replay_identity!=request.replay_identity||a.semantic_profile!="aurora-canonical"{omitted.insert(a.artifact_id.clone());loss.insert(format!("{}:profile-or-replay",a.artifact_id));}else if a.evidence_state=="unknown"||a.evidence_state=="unmeasured"{unknown.insert(a.artifact_id.clone());}else if Some(a.canonical_digest.clone())==baseline{matched.insert(a.artifact_id.clone());}else{mismatched.insert(a.artifact_id.clone());loss.insert(format!("{}:canonical-digest-mismatch",a.artifact_id));}}let global=!request.policy_allowed||!request.protected_closure||!request.signed_approval||!request.network_available||!request.raw_data_local||!request.aggregate_only||!request.adversarial_events.is_empty();if global{omitted.extend(artifacts.iter().cloned());matched.clear();mismatched.clear();unknown.clear();}let langs_ok=request.required_language_order.iter().all(|l|languages.contains(l));let fields_ok=request.required_field_order.iter().all(|f|fields.contains(f));let disposition=if global{"blocked"}else if !langs_ok||!fields_ok||!mismatched.is_empty()||!omitted.is_empty()||!unknown.is_empty(){"unresolved"}else{"parity"};if !langs_ok{loss.insert("required-language-missing".into());}if !fields_ok{loss.insert("required-field-missing".into());}let mut payload=json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"contract_version":version,"feature_id":id,"mode":mode,"scale":scale,"request_id":request.request_id,"disposition":disposition,"language_order":languages.into_iter().collect::<Vec<_>>(),"artifact_order":artifacts,"matched_order":matched.into_iter().collect::<Vec<_>>(),"mismatched_order":mismatched.into_iter().collect::<Vec<_>>(),"omitted_order":omitted.into_iter().collect::<Vec<_>>(),"unknown_order":unknown.into_iter().collect::<Vec<_>>(),"negative_evidence_order":negative.into_iter().collect::<Vec<_>>(),"field_order":fields.into_iter().collect::<Vec<_>>(),"semantic_loss_order":loss.into_iter().collect::<Vec<_>>(),"replay_identity":request.replay_identity,"raw_data_local":true,"aggregate_only":true,"boundary":PRECLINICAL_BOUNDARY});let digest=ContentHash::of_value(&payload).map_err(|e|SemanticParityError::Output(e.to_string()))?;payload["parity_digest"]=json!(digest);payload["artifact"]=json!({"artifact_id":format!("worldgen-semantic-parity:{}",request.request_id),"content_type":CONTENT_TYPE,"content_hash":digest,"semantic_loss":payload["semantic_loss_order"],"provenance_digests":provenance.into_iter().collect::<Vec<_>>(),"boundary":PRECLINICAL_BOUNDARY});payload["effect_receipts"]=json!(if disposition=="parity"{vec![format!("emit:parity-card:{}",request.request_id)]}else{vec!["block:unsafe-release".to_string()]});let out:SemanticParityCard7=serde_json::from_value(payload).map_err(|e|SemanticParityError::Output(e.to_string()))?;out.validate()?;Ok(out)}
